<?php require_once __DIR__.'/../helpers/bootstrap.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $s=db()->prepare('SELECT * FROM users WHERE email=?'); $s->execute([trim($_POST['email']??'')]); $u=$s->fetch(); if($u && password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=$u;redirect('dashboard.php');} $error='Email atau password salah.';} ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Masuk</title><link rel="stylesheet" href="../assets/css/app.css"></head><body class="login"><form method="post"><h1>Stockroom</h1><p>Inventory Management System</p><?php if(!empty($error)):?><div class="error"><?=e($error)?></div><?php endif?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button>Masuk</button><small>Demo: admin@example.com / password</small></form></body></html>
